namespace Studio.Formats.Assets;

/// <summary>Binary constants required by the device formats (from STUdio, MPL-2.0).</summary>
internal static class EmbeddedData
{
    /// <summary>
    /// Short silent MP3 (mono, 44100 Hz, no ID3) used when a stage node has no audio:
    /// the firmware requires every stage node to reference a sound.
    /// </summary>
    public static readonly byte[] BlankMp3 = Convert.FromHexString(
        "");

    /// <summary>Trailer appended to raw (firmware v1) pack images.</summary>
    public static readonly byte[] V1CheckBytes = Convert.FromHexString(
        "");
}
